(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.03-t*0.5)*8+Math.cos(mx*0.025+t*0.4)*6;
  const w2y = Math.cos(mx*0.028+t*0.45)*8+Math.sin(my*0.022-t*0.55)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.7+3)*70,40+Math.cos(t*0.45+4)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.65+1)*70,0.085,1.8]
  ];
  let aS=0,iS=0,sS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    sS+=Math.sin(d*f*1.3-t*sp*0.8+3.0);
  }
  const act=aS/8,inh=iS/8,sec=sS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.065+sy*0.055-t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.03-ang*2+t*0.9)*0.2+Math.sin(dist*0.07+ang*5-t*2.1)*0.15;
  const vortex=Math.sin(ang*6+dist*0.02-t*1.3)*Math.exp(-dist*0.003)*0.3;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3
    +Math.sin(sx*0.2)*Math.sin(sy*0.18)*Math.cos(sx*0.1-sy*0.12+t*0.7)*0.15;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((sec-act*0.4+inh*0.3+vortex)*1.8);
  const rd=Math.tanh(r1*0.65+r2*0.35+cell*0.2);
  const glow=Math.exp(-dist*0.004)*(0.7+0.3*Math.sin(t*0.8+dist*0.02));
  const blend=rd*(0.7+glow*0.3)+cell*0.15,v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,55,95],[18,110,125],[35,155,140],[120,185,120],[210,195,80],[230,150,65],[200,85,55],[140,40,60],[70,20,65],[25,15,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(rd*Math.PI)*0.25;
  const edge=Math.abs(rd)>0.65?1.18:(Math.abs(rd)<0.15?0.88:1.0);
  const sat=1.0+Math.abs(r2)*0.12;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*sat)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*sat)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*sat)|0
  ];
}
